{"claims": [
  {"page": 96, "locator": "", "span": "It is interesting that across the entire blowoff branch, the vaporization ratio is ~70 percent, whereas it drops precipitously to 20 percent at low a along the quenching branch.", "statement": "The vaporization ratio is approximately 70 percent across the blowoff branch and drops to 20 percent at low stretch rates along the quenching branch.", "variables": ["other"], "conditions": {"gravity_class": "not_stated", "gravity_g": null, "oxygen_fraction_min": null, "oxygen_fraction_max": null, "pressure_kpa_min": null, "pressure_kpa_max": null, "flow_cm_s_min": null, "flow_cm_s_max": null, "material": null, "geometry": null}, "effect_direction": "not_applicable", "magnitude_text": "", "evidence_type": "observation", "extraction_confidence": "high"},
  {"page": 96, "locator": "", "span": "As a is reduced, the solid-phase conductive loss ratio surprisingly decreases for this geometry, which is consistent with the observation that the slowest burning rods have the least conductive loss.", "statement": "Reducing the stretch rate decreases the solid-phase conductive loss ratio.", "variables": ["other"], "conditions": {"gravity_class": "not_stated", "gravity_g": null, "oxygen_fraction_min": null, "oxygen_fraction_max": null, "pressure_kpa_min": null, "pressure_kpa_max": null, "flow_cm_s_min": null, "flow_cm_s_max": null, "material": null, "geometry": null}, "effect_direction": "decreases", "magnitude_text": "", "evidence_type": "observation", "extraction_confidence": "high"},
  {"page": 96, "locator": "", "span": "The transition from blowoff to quenching occurs when the forced-flow velocity becomes the same order as the diffusive velocity (U/UD = 1) for this geometry.", "statement": "The transition from blowoff to quenching occurs when the forced-flow velocity equals the diffusive velocity.", "variables": ["flow_velocity"], "conditions": {"gravity_class": "not_stated", "gravity_g": null, "oxygen_fraction_min": null, "oxygen_fraction_max": null, "pressure_kpa_min": null, "pressure_kpa_max": null, "flow_cm_s_min": null, "flow_cm_s_max": null, "material": null, "geometry": null}, "effect_direction": "threshold", "magnitude_text": "U/UD = 1", "evidence_type": "observation", "extraction_confidence": "high"},
  {"page": 97, "locator": "", "span": "The normal-gravity upward limiting O2 concentration of 15.4 percent O2 (Ref. 23) is plotted for comparison, assuming linear superposition of the buoyant flow velocity at the base of the flame (20 cm/s (Ref. 32)) and the 4-cm/s forced-flow velocity.", "statement": "The normal-gravity upward limiting oxygen concentration is 15.4 percent.", "variables": ["oxygen_concentration"], "conditions": {"gravity_class": "earth_1g", "gravity_g": null, "oxygen_fraction_min": null, "oxygen_fraction_max": null, "pressure_kpa_min": null, "pressure_kpa_max": null, "flow_cm_s_min": null, "flow_cm_s_max": null, "material": null, "geometry": null}, "effect_direction": "not_applicable", "magnitude_text": "15.4 percent", "evidence_type": "measurement", "extraction_confidence": "high"},
  {"page": 97, "locator": "", "span": "Ignition delay time increased significantly as the minimum limiting O2 concentration is approached.", "statement": "Ignition delay time increases as the minimum limiting oxygen concentration is approached.", "variables": ["ignition", "oxygen_concentration"], "conditions": {"gravity_class": "microgravity", "gravity_g": null, "oxygen_fraction_min": null, "oxygen_fraction_max": null, "pressure_kpa_min": null, "pressure_kpa_max": null, "flow_cm_s_min": null, "flow_cm_s_max": null, "material": null, "geometry": null}, "effect_direction": "increases", "magnitude_text": "", "evidence_type": "observation", "extraction_confidence": "high"},
